// em/terreno 3.3 (13/11: pag. 4 fine/sync/key track, pag. 5 DRUM; prima 1.0 fase 2): un punto (x, y) corre sopra una superficie z = f(x, y) e l'altezza del punto e' il campione.
//   SYN1  TUNX WAVX SIZX CNTX | TUNY WAVY SIZY CNTY      SYN2  BANK TERR WARP GRAN | MODX MODY FDBK ANGO
// BANK  4 banchi di 8 superfici; TERR scorre (e sfuma) tra le 8 del banco:
//     0 CLASSICI  SENO GRIG PIEG ONDA CERC SELL MOLT RUMO
//     1 ARMONICI  ORGN OTTA DISP FOND CLAR OTTO CORO BRIL
//     2 SPIGOLI   CRIN ROMB PIRA GRAD PIEG LAMA TRIA DENT
//     3 CAOS      SPIR INTF VORT LOGI SCHE DENS STAT RUM2
//     4 FM        FM11 FM12 FM32 FMXY FBCK RING INDX NOIS
//     5 FOLD      FLD1 FLD2 FLD4 ASIM RADI SINF CROS DEEP
//     6 BITS      STEP STRX CHEK PULS XORB SAWQ STAI CRSH
//     7 CHEB      T2 T3 T5 T2T3 T3T5 ODD EVEN FULL
// Indirizzi: lo stato e' in spazio a byte. DM(k, I) e DM(I, M) scalano k e M per 4; MODIFY(I, n) somma n byte.
// Stato per voce (192 parole; le prime 16 azzerate a ogni nota): {'phx': 0, 'phy': 1, 'zprev': 2, 'count': 3, 'dcx': 4, 'dcy': 5, 'wyp': 6, 'out': 16, 'fb': 17, 'morph': 18, 'warpw': 19, 'warps': 20, 'level': 21, 'noise': 22, 'gstep': 23, 'ginv': 24, 'kseg': 25, 'ktri': 26, 'one': 27, 'ksin': 28, 'cy': 29, 'var': 30, 'cx': 32, 'A': 33, 'B': 34, 'C': 35, 'D': 36, 'incx': 37, 'incy': 38, 'modx': 39, 'mody': 40, 'terr_s': 41, 'sizx_s': 42, 'sizy_s': 43, 'ca': 44, 'sa': 45, 'copy': 46}
// x del blocco 70..101, y 102..133.

#include "dk_machine.inc"

.SECTION/PM seg_pmco;
.GLOBAL _ter_render;
.GLOBAL _ter_note_on;
.EXTERN _dv_exp2;

_ter_render:
    I3 = R4;                              // lo stato
    I2 = R8;                              // l'ingresso della voce
    I1 = R12;                             // i parametri (24)
    CALL _ter_cpy;                         // I1 -> copia delle 24 manopole
    R0 = DM(0, I1);
    DM(172, I3) = R0;
    R0 = DM(1, I1);
    DM(173, I3) = R0;
    R0 = DM(2, I1);
    DM(174, I3) = R0;
    R0 = DM(3, I1);
    DM(175, I3) = R0;
    R0 = DM(4, I1);
    DM(176, I3) = R0;
    R0 = DM(5, I1);
    DM(177, I3) = R0;
    R0 = DM(6, I1);
    DM(178, I3) = R0;
    R0 = DM(7, I1);
    DM(179, I3) = R0;
    R0 = DM(8, I1);
    DM(180, I3) = R0;
    R0 = DM(9, I1);
    DM(181, I3) = R0;
    R0 = DM(10, I1);
    DM(182, I3) = R0;
    R0 = DM(11, I1);
    DM(183, I3) = R0;
    R0 = DM(12, I1);
    DM(184, I3) = R0;
    R0 = DM(13, I1);
    DM(185, I3) = R0;
    R0 = DM(14, I1);
    DM(186, I3) = R0;
    R0 = DM(15, I1);
    DM(187, I3) = R0;
    R0 = DM(180, I3);
    DM(0, I1) = R0;
    R0 = DM(181, I3);
    DM(1, I1) = R0;
    R0 = DM(182, I3);
    DM(2, I1) = R0;
    R0 = DM(176, I3);
    DM(3, I1) = R0;
    R0 = DM(184, I3);
    DM(4, I1) = R0;
    R0 = DM(185, I3);
    DM(5, I1) = R0;
    R0 = DM(186, I3);
    DM(6, I1) = R0;
    R0 = DM(177, I3);
    DM(7, I1) = R0;
    R0 = DM(173, I3);
    DM(8, I1) = R0;
    R0 = DM(174, I3);
    DM(9, I1) = R0;
    R0 = DM(175, I3);
    DM(10, I1) = R0;
    R0 = DM(179, I3);
    DM(12, I1) = R0;
    R0 = DM(18, I1);
    DM(11, I1) = R0;
    R0 = DM(23, I1);
    R0 = LSHIFT R0 BY -1;
    DM(14, I1) = R0;
    R0 = 0;
    DM(15, I1) = R0;
    DM(13, I1) = R0;
    R0 = 0x4000;
    DM(2, I1) = R0;
    DM(6, I1) = R0;
    R0 = DM(178, I3);
    DM(166, I3) = R0;
    R0 = DM(183, I3);
    DM(167, I3) = R0;
    R0 = DM(187, I3);
    DM(168, I3) = R0;
    // ---- 3.3 (13/11): pagina 4 (fine e key tracking di fase e PD, sync) e pagina 5 (DRUM), parole 24..39 della chiamata.
    I4 = R12;
    R2 = DM(DK_IN_W_PITCH, I2);
    R3 = 15360;                           // C4: nota 60 * 256
    R2 = R2 - R3;
    R9 = 0x4000;
    R11 = 0x7fff;
    R12 = 0;
    R10 = 0x7f00;
    R0 = DM(182, I3);
    R1 = DM(24, I4);
    R1 = R1 - R9;
    R1 = ASHIFT R1 BY -6;                 // fine: +-1 passo di fase
    R0 = R0 + R1;
    R0 = R0 AND R11;                      // la fase gira
    DM(182, I3) = R0;
    R0 = DM(186, I3);
    R1 = DM(25, I4);
    R1 = R1 - R9;
    R1 = ASHIFT R1 BY -6;                 // fine: +-1 passo di fase
    R0 = R0 + R1;
    R0 = R0 AND R11;                      // la fase gira
    DM(186, I3) = R0;
    R0 = DM(182, I3);
    R1 = DM(28, I4);
    R1 = R1 - R9;
    R1 = ASHIFT R1 BY -8;                 // -64 .. +63
    R1 = R1 * R2 (SSI);
    R1 = ASHIFT R1 BY -6;                 // a +63: un passo (0x100) per semitono
    R0 = R0 + R1;
    R0 = R0 AND R11;                      // la fase gira
    DM(182, I3) = R0;
    R0 = DM(186, I3);
    R1 = DM(29, I4);
    R1 = R1 - R9;
    R1 = ASHIFT R1 BY -8;                 // -64 .. +63
    R1 = R1 * R2 (SSI);
    R1 = ASHIFT R1 BY -6;                 // a +63: un passo (0x100) per semitono
    R0 = R0 + R1;
    R0 = R0 AND R11;                      // la fase gira
    DM(186, I3) = R0;
    R0 = DM(167, I3);
    R1 = DM(30, I4);
    R1 = R1 - R9;
    R1 = ASHIFT R1 BY -8;                 // -64 .. +63
    R1 = R1 * R2 (SSI);
    R1 = ASHIFT R1 BY -6;                 // a +63: un passo (0x100) per semitono
    R0 = R0 + R1;
    R0 = MAX(R0, R12);
    R0 = MIN(R0, R10);
    DM(167, I3) = R0;
    R0 = DM(168, I3);
    R1 = DM(31, I4);
    R1 = R1 - R9;
    R1 = ASHIFT R1 BY -8;                 // -64 .. +63
    R1 = R1 * R2 (SSI);
    R1 = ASHIFT R1 BY -6;                 // a +63: un passo (0x100) per semitono
    R0 = R0 + R1;
    R0 = MAX(R0, R12);
    R0 = MIN(R0, R10);
    DM(168, I3) = R0;
    R0 = DM(26, I4);
    DM(209, I3) = R0;                     // SYNC X, Y: si usano dopo il calcolo dei passi
    R0 = DM(27, I4);
    DM(210, I3) = R0;
    // sweep di pitch (STIM SDEP, come FM DRUM): ottave in piu' = SDEP/127 * 6 * 2^(-campioni dalla nota / T)
    R0 = 0;
    DM(198, I3) = R0;
    R0 = DM(33, I4);
    R0 = PASS R0;
    IF EQ JUMP _ter_sw_no;
    R0 = DM(32, I4);
    F0 = FLOAT R0;
    R1 = 0x39c18306;
    F0 = F0 * F1;
    R1 = 0x4092b803;
    F0 = F0 + F1;
    F0 = -F0;
    CALL _dv_exp2;                        // 1/T
    F0 = -F0;
    R1 = DM(3, I3);
    F1 = FLOAT R1;
    F0 = F0 * F1;                         // -c/T
    R1 = 0xc2700000;
    F0 = MAX(F0, F1);
    CALL _dv_exp2;
    R1 = DM(33, I4);
    F1 = FLOAT R1;
    F0 = F0 * F1;
    R1 = 0x39418306;
    F0 = F0 * F1;
    DM(198, I3) = R0;
_ter_sw_no:
    // rumore (N.HLD N.DEC BASE WDTH GRAN N.LEV, come FM DRUM)
    R0 = 0;
    DM(199, I3) = R0;
    R0 = DM(39, I4);
    R0 = PASS R0;
    IF EQ JUMP _ter_nz_no;
    R0 = DM(34, I4);                      // tenuta: (N.HLD/127)^2 * 48000 campioni
    F0 = FLOAT R0;
    R1 = 0x38010204;
    F0 = F0 * F1;
    F0 = F0 * F0;
    R1 = 0x473b8000;
    F0 = F0 * F1;
    R1 = DM(3, I3);
    F1 = FLOAT R1;
    F1 = F1 - F0;                         // campioni oltre la tenuta
    R0 = 0x3f800000;
    F1 = PASS F1;
    IF LE JUMP _ter_nz_env;
    DM(211, I3) = R1;
    R0 = DM(35, I4);
    F0 = FLOAT R0;
    R1 = 0x39c18306;
    F0 = F0 * F1;
    R1 = 0x4092b803;
    F0 = F0 + F1;
    F0 = -F0;
    CALL _dv_exp2;                        // 1/T
    F0 = -F0;
    R1 = DM(211, I3);
    F0 = F0 * F1;
    R1 = 0xc2700000;
    F0 = MAX(F0, F1);
    CALL _dv_exp2;
_ter_nz_env:
    R1 = DM(39, I4);
    F1 = FLOAT R1;
    R2 = 0x38010204;
    F1 = F1 * F2;
    F1 = F1 * F1;
    R2 = 0x3f000000;
    F1 = F1 * F2;
    F0 = F0 * F1;
    DM(199, I3) = R0;
    R0 = DM(36, I4);                      // BASE: passa-alto 20 Hz * 2^(BASE*10/127)
    F0 = FLOAT R0;
    R1 = 0x39a14285;
    F0 = F0 * F1;
    DM(212, I3) = R0;
    R1 = 0x408a4d3c;                  // log2 20
    F0 = F0 + F1;
    R1 = 0xc14e829f;                // log2(2 pi / 48000)
    F0 = F0 + F1;
    CALL _dv_exp2;                        // w = 2 pi fc / fs
    R1 = 0x3f7fbe77;
    F0 = MIN(F0, F1);
    R1 = 0x3f800000;
    F0 = F1 - F0;
    DM(200, I3) = R0;                     // a = 1 - w
    R0 = DM(37, I4);                      // WDTH: passa-basso a BASE * 2^(WDTH*8/127)
    F0 = FLOAT R0;
    R1 = 0x39810204;
    F0 = F0 * F1;
    R1 = DM(212, I3);
    F0 = F0 + F1;
    R1 = 0xc1095c01;
    F0 = F0 + F1;
    R1 = 0x00000000;
    F0 = MIN(F0, F1);
    CALL _dv_exp2;
    DM(201, I3) = R0;                     // b = min(1, 2 pi fc / fs)
    R0 = DM(38, I4);                      // GRAN: un valore di rumore ogni 1 .. 32 campioni
    R0 = LSHIFT R0 BY -8;
    R0 = LSHIFT R0 BY -2;
    R0 = R0 + 1;
    DM(202, I3) = R0;
_ter_nz_no:
    R5 = DM(3, I3);
    R0 = DK_BLOCK;
    R5 = R0 + R5;
    DM(3, I3) = R5;
    R0 = DM(DK_IN_W_OUT, I2);
    DM(16, I3) = R0;
    R0 = _ter_sin;
    I4 = R0;
    R1 = 1024;
    R0 = R0 + R1;
    I5 = R0;                              // la derivata, 256 parole dopo
    R0 = R0 + R1;
    DM(22, I3) = R0;            // la griglia del rumore, 512 parole dopo
    R8 = 255;                             // maschera della tabella del seno
    // ---- costanti delle onde ----
    R0 = 0xb0000000;
    DM(25, I3) = R0;
    R0 = 0xb0800000;
    DM(26, I3) = R0;
    R0 = 0x3f800000;
    DM(27, I3) = R0;
    R0 = 0x33800000;
    DM(28, I3) = R0;
    // ---- la nota e i passi degli assi ----
    R0 = DM(DK_IN_W_PITCH, I2);
    F0 = FLOAT R0;
    R1 = 0x39aaaaab;                      // 1/3072
    F0 = F0 * F1;
    R1 = 0xc1484fa3;
    F10 = F0 + F1;                        // log2 dell'incremento della nota (cicli per campione)
    R0 = DM(198, I3);                     // 3.3: lo sweep di pitch (ottave)
    F10 = F10 + F0;
    R0 = DM(172, I3);             // 2.0: TUNE (la parola della pag. 1 messa da parte da permuta)
    R1 = 0x4000;
    R0 = R0 - R1;
    F0 = FLOAT R0;
    R1 = 0x39aaaaab;
    F0 = F0 * F1;
    F10 = F10 + F0, R0 = DM(0, I1);
    R1 = 0x4000;
    R0 = R0 - R1;
    F0 = FLOAT R0;
    R1 = 0x39aaaaab;
    F0 = F0 * F1;
    F0 = F0 + F10;
    R1 = 0xbf9374d6;
    F0 = MIN(F0, F1);
    CALL _dv_exp2;
    R1 = 0x4f800000;
    F0 = F0 * F1;
    R0 = FIX F0;
    DM(37, I3) = R0;
    R0 = DM(4, I1);
    R1 = 0x4000;
    R0 = R0 - R1;
    F0 = FLOAT R0;
    R1 = 0x39aaaaab;
    F0 = F0 * F1;
    F0 = F0 + F10;
    R1 = 0xbf9374d6;
    F0 = MIN(F0, F1);
    CALL _dv_exp2;
    R1 = 0x4f800000;
    F0 = F0 * F1;
    R0 = FIX F0;
    DM(38, I3) = R0;
    R0 = DM(37, I3);             // 16 punti per blocco: passi doppi
    R0 = R0 + R0;
    DM(37, I3) = R0;
    R0 = DM(38, I3);
    R0 = R0 + R0;
    DM(38, I3) = R0;
    // ---- 3.3: SYNC X/Y. A 0: passo master 0, nessun azzeramento (suono identico). Altrimenti l'asse corre 2^(SYNC*4/127) volte
    // piu' veloce e la sua fase riparte da 0 a ogni giro della fase master (che va al passo di prima).
    R0 = 0;
    DM(196, I3) = R0;
    R0 = DM(209, I3);
    R0 = PASS R0;
    IF EQ JUMP _ter_sy0_no;
    R1 = DM(37, I3);
    DM(196, I3) = R1;
    F0 = FLOAT R0;
    R1 = 0x39010204;
    F0 = F0 * F1;
    CALL _dv_exp2;
    R1 = DM(37, I3);
    F1 = FLOAT R1;
    F0 = F0 * F1;
    R1 = 0x4effffff;
    F0 = MIN(F0, F1);
    R0 = FIX F0;
    DM(37, I3) = R0;
_ter_sy0_no:
    R0 = 0;
    DM(197, I3) = R0;
    R0 = DM(210, I3);
    R0 = PASS R0;
    IF EQ JUMP _ter_sy1_no;
    R1 = DM(38, I3);
    DM(197, I3) = R1;
    F0 = FLOAT R0;
    R1 = 0x39010204;
    F0 = F0 * F1;
    CALL _dv_exp2;
    R1 = DM(38, I3);
    F1 = FLOAT R1;
    F0 = F0 * F1;
    R1 = 0x4effffff;
    F0 = MIN(F0, F1);
    R0 = FIX F0;
    DM(38, I3) = R0;
_ter_sy1_no:
    // ---- dimensioni (lisciate), angolo, centro ----
    R0 = DM(2, I1);
    F0 = FLOAT R0;
    R1 = 0x38010204;
    F0 = F0 * F1;
    R1 = 0x3f8ccccd;
    F0 = F0 * F1;
    R1 = 0x3da3d70a;
    F0 = F0 + F1;
    R1 = DM(42, I3);
    R2 = DM(3, I3);
    R3 = 32;
    COMP(R2, R3);
    IF EQ F1 = PASS F0;
    F0 = F0 - F1;
    R2 = 0x3e99999a;
    F0 = F0 * F2;
    F0 = F0 + F1;
    DM(42, I3) = R0;
    R0 = DM(6, I1);
    F0 = FLOAT R0;
    R1 = 0x38010204;
    F0 = F0 * F1;
    R1 = 0x3f8ccccd;
    F0 = F0 * F1;
    R1 = 0x3da3d70a;
    F0 = F0 + F1;
    R1 = DM(43, I3);
    R2 = DM(3, I3);
    R3 = 32;
    COMP(R2, R3);
    IF EQ F1 = PASS F0;
    F0 = F0 - F1;
    R2 = 0x3e99999a;
    F0 = F0 * F2;
    F0 = F0 + F1;
    DM(43, I3) = R0;
    R0 = DM(63, I3);        // 3.2 ROTA -64..+63: angolo = (r - 0x4000) / 32768 giri, sotto lo 0 piu' un giro (al centro 0 esatto)
    R1 = 0x4000;
    R0 = R0 - R1;
    F7 = FLOAT R0;
    R1 = 0x38000000;
    F7 = F7 * F1;
    R1 = 0x3f800000;
    F0 = F7 + F1;
    R1 = 0;
    COMP(F7, F1);
    IF LT F7 = PASS F0;
    R1 = 0x43800000;
    F0 = F7 * F1;
    F6 = PASS F0;
    R1 = FIX F0;
    F3 = FLOAT R1;
    R1 = R1 AND R8;
    M1 = R1;
    F0 = F0 - F3, R2 = DM(M1, I4);
    F0 = PASS F0, R3 = DM(M1, I5);
    F3 = F3 * F0;
    F2 = F2 + F3;
    DM(45, I3) = R2;
    F0 = PASS F6;
    R1 = FIX F0;
    F3 = FLOAT R1;
    R2 = 64;
    R1 = R1 + R2;
    R1 = R1 AND R8;
    M1 = R1;
    F0 = F0 - F3, R2 = DM(M1, I4);
    F0 = PASS F0, R3 = DM(M1, I5);
    F3 = F3 * F0;
    F2 = F2 + F3;
    DM(44, I3) = R2;
    R4 = DM(42, I3);
    R5 = DM(43, I3);
    R0 = DM(62, I3);        // 3.2 ASPT: gx = min(1, 1 - a), gy = min(1, 1 + a), a = -1..1
    R1 = 0x4000;
    R0 = R0 - R1;
    F0 = FLOAT R0;
    R1 = 0x38800000;
    F0 = F0 * F1;
    R1 = 0x3f800000;
    F2 = F1 - F0;
    F2 = MIN(F2, F1);
    F3 = F1 + F0;
    F3 = MIN(F3, F1);
    F4 = F4 * F2;
    F5 = F5 * F3;
    R6 = DM(44, I3);
    R7 = DM(45, I3);
    F0 = F4 * F6;
    DM(33, I3) = R0;                // SIZX cos
    F0 = F5 * F7;
    DM(34, I3) = R0;                // SIZY sin
    F0 = F4 * F7;
    DM(35, I3) = R0;                // SIZX sin
    F0 = F5 * F6;
    DM(36, I3) = R0;                // SIZY cos
    R0 = DM(3, I1);
    R1 = 0x4000;
    R0 = R0 - R1;
    F0 = FLOAT R0;
    R1 = 0x38800000;
    F0 = F0 * F1;
    R1 = 0x400ccccd;                       // 12/11 (v58e): POSX gira tutta la mappa in larghezza (+-2.2, prima +-1)
    F0 = F0 * F1;
    DM(32, I3) = R0;
    R0 = DM(7, I1);
    R1 = 0x4000;
    R0 = R0 - R1;
    F0 = FLOAT R0;
    R1 = 0x38800000;
    F0 = F0 * F1;
    DM(29, I3) = R0;
    R0 = DM(166, I3);
    F0 = FLOAT R0;
    R1 = 0x39010204;
    F0 = F0 * F1;
    R1 = 0xc0000000;
    F0 = F0 + F1;
    CALL _dv_exp2;
    R1 = DM(33, I3);
    F1 = F1 * F0;
    DM(33, I3) = R1;
    R1 = DM(36, I3);
    F1 = F1 * F0;
    DM(36, I3) = R1;
    R1 = DM(34, I3);
    F1 = F1 * F0;
    DM(34, I3) = R1;
    R1 = DM(35, I3);
    F1 = F1 * F0;
    DM(35, I3) = R1;
    R0 = DM(167, I3);
    R1 = 0x4000;
    R0 = R0 - R1;
    F0 = FLOAT R0;
    R1 = 0x38800000;
    F0 = F0 * F1;
    R1 = 0xbef5c28f;
    F0 = F0 * F1;
    R1 = 0x3f000000;
    F5 = F0 + F1;
    R3 = 0x7ef311c7;
    R6 = R3 - R5;
    R3 = 0x40000000;
    F2 = F5 * F6;
    F2 = F3 - F2;
    F6 = F6 * F2;
    F2 = F5 * F6;
    F2 = F3 - F2;
    F6 = F6 * F2;
    F2 = F5 * F6;
    F2 = F3 - F2;
    F6 = F6 * F2;
    R1 = 0x3f000000;
    F6 = F6 * F1;
    R1 = 0x3f800000;
    F0 = F1 - F5;
    R3 = 0x7ef311c7;
    R7 = R3 - R0;
    R3 = 0x40000000;
    F2 = F0 * F7;
    F2 = F3 - F2;
    F7 = F7 * F2;
    F2 = F0 * F7;
    F2 = F3 - F2;
    F7 = F7 * F2;
    F2 = F0 * F7;
    F2 = F3 - F2;
    F7 = F7 * F2;
